<script lang="ts">
 import {onMount} from 'svelte';
 let {lang='en'}=$props<{lang?:'en'|'th'}>();
 const locales=['en','th','ja','zh-CN'];
 const text=lang==='th'?{back:'เครื่องมือผู้ขาย',title:'แค็ตตาล็อกสินค้า',search:'ค้นหาสินค้า',create:'สร้างสินค้า',save:'บันทึกสินค้าทั้งหมด',publish:'เผยแพร่',unpublish:'ยกเลิกเผยแพร่',archive:'เก็บถาวร',preview:'ดูตัวอย่าง',images:'รูปภาพ',options:'ตัวเลือก',skus:'SKU',add:'เพิ่ม',loading:'กำลังโหลด…',error:'บันทึกไม่สำเร็จ การแก้ไขยังอยู่'}:{back:'Seller tools',title:'Product catalog',search:'Search products',create:'Create product',save:'Save complete product',publish:'Publish',unpublish:'Unpublish',archive:'Archive',preview:'Preview',images:'Images',options:'Options',skus:'SKUs',add:'Add',loading:'Loading…',error:'Could not save. Your edits are preserved.'};
 let list=$state<any[]>([]),selected=$state<any>(null),query=$state(''),filter=$state(''),busy=$state(false),message=$state('');
 const labels=()=>Object.fromEntries(locales.map(locale=>[locale,'']));
 async function loadList(){const r=await fetch(`/api/admin/catalog?q=${encodeURIComponent(query)}&lifecycle=${encodeURIComponent(filter)}`,{cache:'no-store'});if(!r.ok)throw Error();list=(await r.json()).products;}
 async function open(id:string){busy=true;message='';try{const r=await fetch(`/api/admin/catalog/${id}`,{cache:'no-store'});if(!r.ok)throw Error();selected=(await r.json()).product;}catch{message=text.error;}finally{busy=false;}}
 async function create(){busy=true;try{const r=await fetch('/api/admin/catalog',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();const {id}=await r.json();await loadList();await open(id);}catch{message=text.error;}finally{busy=false;}}
 async function save(){if(!selected||busy)return;busy=true;message='';try{const r=await fetch(`/api/admin/catalog/${selected.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(selected)});const data=await r.json();if(!r.ok)throw Error(data.error);message=lang==='th'?'บันทึกแล้ว':'Saved.';await loadList();}catch(error){message=`${text.error} ${String((error as Error).message??'')}`;}finally{busy=false;}}
 async function lifecycle(value:string){if(!selected||busy||value==='archived'&&!confirm(lang==='th'?'เก็บสินค้านี้ถาวรหรือไม่':'Archive this product?'))return;busy=true;try{const r=await fetch(`/api/admin/catalog/${selected.id}/lifecycle`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lifecycle:value})});if(!r.ok)throw Error();selected.lifecycle=value;await loadList();}catch{message=text.error;}finally{busy=false;}}
 function addImage(){selected.images=[...selected.images,{url:'https://',alt:'',position:selected.images.length,primary:selected.images.length===0}];}
 function addGroup(){selected.optionGroups=[...selected.optionGroups,{code:'',position:selected.optionGroups.length,labels:labels(),values:[]}];}
 function addValue(group:any){group.values=[...group.values,{code:'',position:group.values.length,labels:labels()}];selected={...selected};}
 function addSku(){selected.skus=[...selected.skus,{sku:'',optionValueCodes:[],onHand:0,reserved:0,usd:null,jpy:null,thb:null,weightKg:null,salesMode:'checkout',lifecycle:'active'}];}
 onMount(()=>loadList().catch(()=>message=text.error));
</script>
<section class="mx-auto max-w-7xl space-y-6 px-4 py-10 md:px-6">
 <a class="btn" href={lang==='th'?'/th/admin':'/admin'}>← {text.back}</a><h1 class="font-serif text-4xl">{text.title}</h1>
 <div class="catalog-layout"><aside><div class="filters"><input class="input" type="search" placeholder={text.search} bind:value={query} onchange={()=>loadList()}/><select class="input" bind:value={filter} onchange={()=>loadList()}><option value="">All</option><option>draft</option><option>published</option><option>archived</option></select><button class="btn btn-primary" onclick={create}>{text.create}</button></div>{#each list as product}<button class:selected={selected?.id===product.id} class="product-row" onclick={()=>open(product.id)}><strong>{product.catalog_product_translations?.find((x:any)=>x.locale===lang)?.name||product.slug}</strong><small>{product.slug} · {product.lifecycle}</small></button>{/each}</aside>
 {#if selected}<form onsubmit={event=>{event.preventDefault();void save();}}><div class="editor-head"><div><label>Slug<input class="input" bind:value={selected.slug} disabled={selected.lifecycle==='published'}/></label><label>Collection slug<input class="input" bind:value={selected.collectionSlug}/></label></div><span class="state">{selected.lifecycle}</span></div>
  <div class="translation-tabs">{#each locales as locale}{@const tr=selected.translations.find((x:any)=>x.locale===locale)}<fieldset><legend>{locale} {tr?.name&&tr?.shortDescription&&tr?.description?'✓':'!'}</legend>{#if tr}<label>Name<input class="input" maxlength="160" bind:value={tr.name}/></label><label>Badge<input class="input" maxlength="80" bind:value={tr.badge}/></label><label>Short description<textarea class="input" maxlength="500" bind:value={tr.shortDescription}></textarea></label><label>Description<textarea class="input tall" maxlength="10000" bind:value={tr.description}></textarea></label>{/if}</fieldset>{/each}</div>
  <section><h2>{text.images}</h2>{#each selected.images as image,i}<div class="row"><input class="input grow" type="url" bind:value={image.url}/><input class="input grow" placeholder="Alt text" bind:value={image.alt}/><label><input type="radio" name="primary" checked={image.primary} onchange={()=>selected.images.forEach((x:any)=>x.primary=x===image)}/> Primary</label><button type="button" class="btn" onclick={()=>selected.images=selected.images.filter((_:any,index:number)=>index!==i)}>×</button></div>{/each}<button type="button" class="btn" onclick={addImage}>{text.add} URL</button></section>
  <section><h2>{text.options}</h2>{#each selected.optionGroups as group}<div class="card"><label>Code<input class="input" bind:value={group.code}/></label><div class="labels">{#each locales as locale}<label>{locale}<input class="input" bind:value={group.labels[locale]}/></label>{/each}</div>{#each group.values as value}<div class="row"><input class="input" placeholder="Value code" bind:value={value.code}/>{#each locales as locale}<input class="input" placeholder={locale} bind:value={value.labels[locale]}/>{/each}</div>{/each}<button type="button" class="btn" onclick={()=>addValue(group)}>{text.add} value</button></div>{/each}<button type="button" class="btn" onclick={addGroup}>{text.add} option</button></section>
  <section><h2>{text.skus}</h2><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Options</th><th>Stock / reserved</th><th>USD / JPY / THB</th><th>kg</th><th>Mode</th><th>State</th></tr></thead><tbody>{#each selected.skus as sku}<tr><td><input class="input" bind:value={sku.sku} disabled={selected.lifecycle==='published'}/></td><td><input class="input" value={sku.optionValueCodes.join(', ')} onchange={e=>sku.optionValueCodes=e.currentTarget.value.split(',').map(x=>x.trim()).filter(Boolean)}/></td><td><input class="input small" inputmode="numeric" bind:value={sku.onHand}/> / {sku.reserved}</td><td><input class="input tiny" inputmode="decimal" bind:value={sku.usd}/> <input class="input tiny" inputmode="numeric" bind:value={sku.jpy}/> <input class="input tiny" inputmode="decimal" bind:value={sku.thb}/></td><td><input class="input small" inputmode="decimal" bind:value={sku.weightKg}/></td><td><select class="input" bind:value={sku.salesMode}><option value="checkout">checkout</option><option value="reservation_only">reservation only</option></select></td><td><select class="input" bind:value={sku.lifecycle}><option>active</option><option>archived</option></select></td></tr>{/each}</tbody></table></div><button type="button" class="btn" onclick={addSku}>{text.add} SKU</button></section>
  <div class="actions"><button class="btn btn-primary" disabled={busy}>{text.save}</button>{#if selected.lifecycle!=='published'}<button type="button" class="btn" onclick={()=>lifecycle('published')}>{text.publish}</button>{:else}<button type="button" class="btn" onclick={()=>lifecycle('draft')}>{text.unpublish}</button>{/if}<button type="button" class="btn danger" onclick={()=>lifecycle('archived')}>{text.archive}</button>{#if selected.lifecycle==='published'}<a class="btn" target="_blank" href={`${lang==='en'?'':'/'+lang}/product/${selected.slug}`}>{text.preview}</a>{/if}</div>
 </form>{:else}<p>{busy?text.loading:''}</p>{/if}</div><p role="status">{message}</p>
</section>
<style>.catalog-layout{display:grid;grid-template-columns:18rem minmax(0,1fr);gap:1.5rem}aside,form{border:1px solid #ffffff22;border-radius:1rem;padding:1rem;background:#1115}.filters{display:grid;gap:.6rem;margin-bottom:1rem}.product-row{display:grid;width:100%;padding:.8rem;text-align:left;border-top:1px solid #ffffff18}.product-row.selected{background:#ffffff12}.product-row small{color:#aaa}.editor-head,.row,.actions{display:flex;gap:.7rem;align-items:end;flex-wrap:wrap}.editor-head{justify-content:space-between}.state{padding:.35rem .7rem;border:1px solid #ffffff33;border-radius:99px}.translation-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin-block:1.5rem}.translation-tabs fieldset,.card,form>section{border:1px solid #ffffff20;border-radius:.7rem;padding:1rem}.translation-tabs label,.card label{display:grid;gap:.25rem;margin-top:.55rem}.tall{min-height:8rem}.grow{flex:1 1 15rem}.labels{display:grid;grid-template-columns:repeat(4,1fr);gap:.5rem}.table-wrap{overflow:auto}table{min-width:1050px;width:100%;border-collapse:collapse}th,td{padding:.5rem;border-bottom:1px solid #ffffff18;text-align:left}.small{width:5rem}.tiny{width:5.5rem}.danger{border-color:#a55;color:#fcc}.actions{position:sticky;bottom:0;padding:1rem;background:#101313eF;margin-top:1rem}@media(max-width:850px){.catalog-layout{grid-template-columns:1fr}.translation-tabs{grid-template-columns:1fr}.labels{grid-template-columns:1fr 1fr}}</style>
